  "tt.profile": { en: "Keycap profile/row. Common: OEM / DCS / DSA / SA / CHICKLET / FLAT. Row-suffix like DCS R1.", zh: "按键帽高度轮廓/行号。常见值：OEM / DCS / DSA / SA / CHICKLET / FLAT，可按行细分如 DCS R1", "ja": "キーキャッププロファイル/段。代表例：OEM/DCS/DSA/SA/CHICKLET/FLAT。「DCS R1」のような段サフィックス。", "pt": "Perfil/linha da tecla. Comuns: OEM/DCS/DSA/SA/CHICKLET/FLAT. Sufixo de linha como DCS R1.", "ko": "키캡 프로필/열. 일반: OEM/DCS/DSA/SA/CHICKLET/FLAT. DCS R1과 같은 열 접미사.", "es": "Perfil/fila de tecla. Comunes: OEM/DCS/DSA/SA/CHICKLET/FLAT. Sufijo de fila como DCS R1.", "fr": "Profil/rangée du capuchon. Courants : OEM/DCS/DSA/SA/CHICKLET/PLAT. Suffixe de rangée comme DCS R1.", "ru": "Профиль/ряд колпачка. Распространённые: OEM/DCS/DSA/SA/CHICKLET/FLAT. Суффикс ряда, например DCS R1.", "zh-TW": "鍵帽高度/列。常見：OEM/DCS/DSA/SA/CHICKLET/FLAT。列後綴如 DCS R1。" },
  "tt.switchMount": { en: "Switch mount type (compatibility)", zh: "轴体安装类型（接口兼容性）", "ja": "スイッチマウントタイプ（互換性）", "pt": "Tipo de montagem do switch (compatibilidade)", "ko": "스위치 마운트 유형 (호환성)", "es": "Tipo de montaje del interruptor (compatibilidad)", "fr": "Type de montage de l'interrupteur (compatibilité)", "ru": "Тип установки переключателя (совместимость)", "zh-TW": "軸體安裝類型（相容性）" },
  "tt.switchBrand": { en: "Switch brand (selecting brand filters Type)", zh: "轴体品牌（选取品牌后Type过滤对应型号）", "ja": "スイッチブランド（ブランドを選択するとタイプがフィルターされます）", "pt": "Marca do switch (selecionar marca filtra o Tipo)", "ko": "스위치 브랜드 (브랜드 선택 시 타입 필터링)", "es": "Marca del interruptor (seleccionar marca filtra el Tipo)", "fr": "Marque de l'interrupteur (la sélection de la marque filtre le Type)", "ru": "Бренд переключателя (выбор бренда фильтрует тип)", "zh-TW": "軸體品牌（選擇品牌會篩選類型）" },
  "tt.switchType": { en: "Switch feel type (linear/tactile/clicky)", zh: "轴体手感类型（线性/段落/清脆等）", "ja": "スイッチのフィールタイプ（リニア/タクタイル/クリッキー）", "pt": "Tipo de sensação do switch (linear/tátil/clicky)", "ko": "스위치 느낌 유형 (리니어/택타일/클리키)", "es": "Tipo de sensación del interruptor (lineal/táctil/clicky)", "fr": "Type de sensation de l'interrupteur (linéaire/tactile/cliquable)", "ru": "Тип ощущения переключателя (линейный/тактильный/кликовый)", "zh-TW": "軸體手感類型（線性/段落/有聲段落）" },
  "tt.ghosted": { en: "Ghosted/transparent effect (opacity 0.4). For overlay layers or indicating alternate functions. Mutually exclusive with Decal.", zh: "半透明效果（透明度0.4），用于叠加图层或指示按键替代功能。与 Decal 互斥", "ja": "ゴースト/半透明効果（不透明度0.4）。オーバーレイレイヤーや代替機能の表示に使用。Decal とは排他的。", "pt": "Efeito fantasma/transparente (opacidade 0.4). Para camadas sobrepostas ou indicação de funções alternativas. Mutuamente exclusivo com Decalque.", "ko": "고스티드/투명 효과 (불투명도 0.4). 오버레이 레이어나 대체 기능 표시용. 데칼과 상호 배타적.", "es": "Efecto fantasma/transparente (opacidad 0.4). Para capas superpuestas o indicar funciones alternativas. Mutuamente excluyente con Calcomanía.", "fr": "Effet fantôme/transparent (opacité 0,4). Pour les calques de superposition ou l'indication de fonctions alternatives. Mutuellement exclusif avec Décal.", "ru": "Эффект полупрозрачности (прозрачность 0.4). Для наложенных слоёв или обозначения альтернативных функций. Взаимоисключающе с Decal.", "zh-TW": "透光/半透明效果（透明度 0.4）。用於覆蓋層或指示替代功能。與「裝飾」互斥。" },
  "tt.stepped": { en: "Stepped key (e.g. Caps Lock), left 25% notch. Auto-adjusts width. Mutually exclusive with Decal.", zh: "阶梯按键（如Caps Lock），左侧25%缩进。开启后自动调节主键宽度。与 Decal 互斥", "ja": "ステップキー（例：Caps Lock）、左側25%切り欠き。幅は自動調整。Decal とは排他的。", "pt": "Tecla em degrau (ex.: Caps Lock), entalhe esquerdo de 25%. Ajusta largura automaticamente. Mutuamente exclusivo com Decalque.", "ko": "스텝드 키 (예: Caps Lock), 왼쪽 25% 노치. 너비 자동 조정. 데칼과 상호 배타적.", "es": "Tecla escalonada (ej. Bloq Mayús), muesca del 25% izquierda. Ajusta el ancho automáticamente. Mutuamente excluyente con Calcomanía.", "fr": "Touche décalée (ex. Caps Lock), encoche gauche 25%. Ajuste automatiquement la largeur. Mutuellement exclusif avec Décal.", "ru": "Ступенчатая клавиша (напр. Caps Lock), вырез слева 25%. Автоматически подстраивает ширину. Взаимоисключающе с Decal.", "zh-TW": "階梯式按鍵（例如大寫鎖定），左側 25% 缺口。自動調整寬度。與「裝飾」互斥。" },
  "tt.homing": { en: "Homing bump/dimples (for F/J touch-typing). Mutually exclusive with Decal.", zh: "定位凸点/凹痕（常用于F/J键辅助盲打定位）。与 Decal 互斥", "ja": "ホーミングバンプ/ディンプル（F/J タッチタイピング用）。Decal とは排他的。", "pt": "Relevo/ranhuras de homing (para F/J na digitação tátil). Mutuamente exclusivo com Decalque.", "ko": "홈 돌기/딤플 (F/J 터치 타이핑용). 데칼과 상호 배타적.", "es": "Relieve/hoyuelos de guía (para F/J de mecanografía). Mutuamente excluyente con Calcomanía.", "fr": "Bosselure/creux de repère (pour la dactylo F/J). Mutuellement exclusif avec Décal.", "ru": "Домашний выступ/углубления (для слепой печати F/J). Взаимоисключающе с Decal.", "zh-TW": "定位凸點/凹痕（用於 F/J 盲打定位）。與「裝飾」互斥。" },
  "tt.decal": { en: "Decal mode — removes labels, forces dimmed opacity. Clears Ghosted/Stepped/Homing. Resets x2/y2 to 0.", zh: "装饰键模式 — 去除标签显示，强制半透明，自动清除 Ghosted/Stepped/Homing。x2/y2归零，第二段等于主键尺寸", "ja": "デカールモード — ラベルを削除し、透明度を低下。Ghosted/Stepped/Homing をクリア。x2/y2 を 0 にリセット。", "pt": "Modo decalque — remove rótulos, força opacidade reduzida. Limpa Fantasma/Degrau/Homing. Redefine x2/y2 para 0.", "ko": "데칼 모드 — 레이블 제거, 흐린 불투명도 강제. Ghosted/Stepped/Homing 해제. x2/y2를 0으로 초기화.", "es": "Modo calcomanía — elimina etiquetas, fuerza opacidad atenuada. Limpia Fantasma/Escalonada/Guía. Reinicia x2/y2 a 0.", "fr": "Mode décal — supprime les étiquettes, force l'opacité réduite. Efface Fantôme/Décalé/Repère. Réinitialise x2/y2 à 0.", "ru": "Режим декали — удаляет подписи, принудительно затемняет. Сбрасывает Ghosted/Stepped/Homing. Обнуляет x2/y2.", "zh-TW": "裝飾模式 — 移除字樣，強制降低不透明度。清除透光/階梯式/定位。將 x2/y2 重設為 0。" },
