  // ─── 导出/保存消息 ───────────────────────────────────────
  "export.svgSuccess": { en: "✅ SVG exported!\nFile: {{path}}", zh: "✅ SVG 导出成功！\n文件: {{path}}", "zh-TW": "✅ SVG 匯出成功！\n檔案: {{path}}", ko: "✅ SVG 내보내기 성공!\n파일: {{path}}", ja: "✅ SVG の書き出しに成功！\nファイル: {{path}}", ru: "✅ SVG экспортирован!\nФайл: {{path}}", fr: "✅ SVG exporté !\nFichier : {{path}}", pt: "✅ SVG exportado!\nArquivo: {{path}}", es: "✅ ¡SVG exportado!\nArchivo: {{path}}" },
  "export.dxfSuccess": { en: "✅ DXF exported!\nFile: {{path}}", zh: "✅ DXF 导出成功！\n文件: {{path}}", "zh-TW": "✅ DXF 匯出成功！\n檔案: {{path}}", ko: "✅ DXF 내보내기 성공!\n파일: {{path}}", ja: "✅ DXF の書き出しに成功！\nファイル: {{path}}", ru: "✅ DXF экспортирован!\nФайл: {{path}}", fr: "✅ DXF exporté !\nFichier : {{path}}", pt: "✅ DXF exportado!\nArquivo: {{path}}", es: "✅ ¡DXF exportado!\nArchivo: {{path}}" },
  "export.kicadSuccess": { en: "✅ KiCad .kicad_pcb exported!\nFile: {{path}}\n\nNext steps:\n1. Open LCEDA format converter\n2. Pick this .kicad_pcb file\n3. Convert to .epro format\n4. Import in LCEDA", zh: "✅ KiCad .kicad_pcb 导出成功！\n文件: {{path}}\n\n下一步:\n1. 打开立创 EDA 格式转换助手\n2. 选择此 .kicad_pcb 文件\n3. 转换为 .epro 格式\n4. 在立创 EDA 中导入", "zh-TW": "✅ KiCad .kicad_pcb 匯出成功！\n檔案: {{path}}\n\n下一步:\n1. 開立立創 EDA 格式轉換助手\n2. 選擇此 .kicad_pcb 檔案\n3. 轉換為 .epro 格式\n4. 在立創 EDA 中匯入", ko: "✅ KiCad .kicad_pcb 내보내기 성공!\n파일: {{path}}\n\n다음 단계:\n1. LCEDA 포맷 변환 도구 열기\n2. 이 .kicad_pcb 파일 선택\n3. .epro 포맷으로 변환\n4. LCEDA에서 가져오기", ja: "✅ KiCad .kicad_pcb の書き出しに成功！\nファイル: {{path}}\n\n次の手順：\n1. LCEDA フォーマット変換ツールを開く\n2. この .kicad_pcb ファイルを選択\n3. .epro 形式に変換\n4. LCEDA でインポート", ru: "✅ KiCad .kicad_pcb экспортирован!\nФайл: {{path}}\n\nДалее:\n1. Откройте конвертер форматов LCEDA\n2. Выберите этот файл .kicad_pcb\n3. Преобразуйте в формат .epro\n4. Импортируйте в LCEDA", fr: "✅ KiCad .kicad_pcb exporté !\nFichier : {{path}}\n\nÉtapes suivantes :\n1. Ouvrir le convertisseur LCEDA\n2. Choisir ce fichier .kicad_pcb\n3. Convertir en format .epro\n4. Importer dans LCEDA", pt: "✅ KiCad .kicad_pcb exportado!\nArquivo: {{path}}\n\nPróximos passos:\n1. Abra o conversor de formato LCEDA\n2. Escolha este arquivo .kicad_pcb\n3. Converta para o formato .epro\n4. Importe no LCEDA", es: "✅ ¡KiCad .kicad_pcb exportado!\nArchivo: {{path}}\n\nSiguientes pasos:\n1. Abre el conversor de formato LCEDA\n2. Elige este archivo .kicad_pcb\n3. Convierte a formato .epro\n4. Importa en LCEDA" },
  "export.kicadProOnly": { en: "🔒 KiCad/LCEDA export is a Professional edition feature.\nThe Professional edition includes production-grade KiCad / LCEDA / QMK firmware export.", zh: "🔒 导出 KiCad/立创EDA 为专业版功能。\n专业版含 KiCad / 立创EDA / QMK 固件生产级导出。", "zh-TW": "🔒 匯出 KiCad/立創EDA 為專業版功能。\n專業版含 KiCad / 立創EDA / QMK 韌體生產級匯出。", ko: "🔒 KiCad/LCEDA 내보내기는 프로페셔널 버전 기능입니다.\n프로페셔널 버전에는 KiCad / LCEDA / QMK 펌웨어 생산급 내보내기가 포함됩니다.", ja: "🔒 KiCad/LCEDA 書き出しはプロフェッショナル版の機能です。\nプロ版には KiCad / LCEDA / QMK ファームウェアの実用レベル書き出しが含まれます。", ru: "🔒 Экспорт KiCad/LCEDA — функция профессиональной версии.\nПрофверсия включает производственный экспорт KiCad / LCEDA / прошивки QMK.", fr: "🔒 L'export KiCad/LCEDA est une fonction de l'édition Professionnelle.\nL'édition Pro inclut l'export de production KiCad / LCEDA / firmware QMK.", pt: "🔒 A exportação KiCad/LCEDA é um recurso da edição Profissional.\nA edição Pro inclui exportação de nível de produção KiCad / LCEDA / firmware QMK.", es: "🔒 La exportación KiCad/LCEDA es una función de la edición Profesional.\nLa edición Pro incluye exportación de grado de producción KiCad / LCEDA / firmware QMK." },
